// Generates encoded detection-string tables from tool/signatures.json.
//
//   dart run tool/gen_signatures.dart          # write the generated files
//   dart run tool/gen_signatures.dart --check  # exit 1 if any generated file is stale
//
// Outputs:
//   src/dsi_signatures.g.h                       (C lists used by src/dsi.c)
//   android/.../generated/Signatures.g.kt        (Kotlin lists)
//   android/src/main/AndroidManifest.xml         (<queries> for the root-app packages)
//
// Each list is joined with NUL separators and XOR-ed with a position-dependent key, so the
// paths and names don't show up in `strings libdsi.so` or a DEX string dump. This is
// obfuscation, not encryption: it raises the cost of finding and patching the lists, nothing
// more.
import 'dart:convert';
import 'dart:io';

const String jsonPath = 'tool/signatures.json';
const String cOut = 'src/dsi_signatures.g.h';
const String kotlinOut =
    'android/src/main/kotlin/com/devamitkumartiwari/device_safety_info/generated/Signatures.g.kt';
const String manifestPath = 'android/src/main/AndroidManifest.xml';

/// Lists the C code needs. Everything else is Kotlin-only, except `ios*` lists, which are C-only.
const Set<String> cLists = {
  'suPaths',
  'rootManagerPaths',
  'mountSources',
  'mountOptionMarkers',
  'protectedMountPoints',
  'protectedMountPrefixes',
  'fridaMapMarkers',
  'fridaThreadNames',
  'fridaFdMarkers',
  'iosJailbreakPaths',
  'iosInjectedImages',
};

/// Packages that get a `<queries>` entry so the package-based checks (root apps, remote access,
/// mock location, cloners) can see them on Android 11+.
const List<String> queriedLists = [
  'rootManagerPackages',
  'rootCloakPackages',
  'remoteAccessPackages',
  'mockLocationPackages',
  'clonerPackages',
];

const String _beginQueries =
    '<!-- BEGIN GENERATED QUERIES (tool/gen_signatures.dart) -->';
const String _endQueries = '<!-- END GENERATED QUERIES -->';

/// Per-list key seed: FNV-1a of the name, forced odd so it's never zero.
int seedFor(String name) {
  var h = 0x811c9dc5;
  for (final c in utf8.encode(name)) {
    h = ((h ^ c) * 0x01000193) & 0xffffffff;
  }
  return (h & 0xff) | 1;
}

/// The key byte at [i] for [seed]. Must match `dsi_sig_key` in dsi.c and `key` in Kotlin.
int keyAt(int seed, int i) => (seed + i * 167) & 0xff;

/// NUL-joined, XOR-encoded bytes of [values].
List<int> encode(String name, List<String> values) {
  final seed = seedFor(name);
  final raw = utf8.encode(values.join('\u0000'));
  return [for (var i = 0; i < raw.length; i++) raw[i] ^ keyAt(seed, i)];
}

/// Inverse of [encode].
List<String> decode(String name, List<int> bytes) {
  final seed = seedFor(name);
  final raw = [
    for (var i = 0; i < bytes.length; i++) bytes[i] ^ keyAt(seed, i),
  ];
  return utf8.decode(raw).split('\u0000');
}

/// The parsed lists, in file order, skipping `_comment`-style keys.
Map<String, List<String>> readLists(String json) {
  final map = jsonDecode(json) as Map<String, dynamic>;
  return {
    for (final e in map.entries)
      if (!e.key.startsWith('_'))
        e.key: [for (final v in e.value as List) v as String],
  };
}

String _snake(String name) =>
    name.replaceAllMapped(RegExp('[A-Z]'), (m) => '_${m[0]}').toUpperCase();

String _hex(int b) => '0x${b.toRadixString(16).padLeft(2, '0')}';

String generateC(Map<String, List<String>> lists) {
  final out = StringBuffer()
    ..writeln(
      '// GENERATED by tool/gen_signatures.dart from tool/signatures.json. Do not edit.',
    )
    ..writeln('// Decode with dsi_sig_next() in dsi.c.')
    ..writeln('#ifndef DSI_SIGNATURES_G_H_')
    ..writeln('#define DSI_SIGNATURES_G_H_')
    ..writeln()
    ..writeln('typedef struct {')
    ..writeln('  const unsigned char* data;')
    ..writeln('  unsigned int len;')
    ..writeln('  unsigned char seed;')
    ..writeln('} dsi_sig_t;');
  for (final MapEntry(key: name, value: values) in lists.entries) {
    if (!cLists.contains(name)) continue;
    final bytes = encode(name, values);
    final id = 'DSI_SIG_${_snake(name)}';
    out
      ..writeln()
      ..writeln('// $name: ${values.length} entries')
      ..writeln(
        '__attribute__((unused)) static const unsigned char ${id}_DATA[] = {',
      );
    for (var i = 0; i < bytes.length; i += 16) {
      final row = bytes.skip(i).take(16).map(_hex).join(', ');
      out.writeln('    $row,');
    }
    out
      ..writeln('};')
      ..writeln(
        '__attribute__((unused)) static const dsi_sig_t $id = '
        '{${id}_DATA, ${bytes.length}u, ${_hex(seedFor(name))}};',
      );
  }
  out
    ..writeln()
    ..writeln('#endif  // DSI_SIGNATURES_G_H_');
  return out.toString();
}

String generateKotlin(Map<String, List<String>> lists) {
  final out = StringBuffer()
    ..writeln(
      '// GENERATED by tool/gen_signatures.dart from tool/signatures.json. Do not edit.',
    )
    ..writeln('package com.devamitkumartiwari.device_safety_info.generated')
    ..writeln()
    ..writeln(
      '/** Detection strings, stored encoded so they don\'t appear in a DEX string dump. */',
    )
    ..writeln('internal object Signatures {');
  for (final MapEntry(key: name, value: values) in lists.entries) {
    if (name.startsWith('ios')) continue;
    final hex = encode(
      name,
      values,
    ).map((b) => b.toRadixString(16).padLeft(2, '0')).join();
    out
      ..writeln()
      ..writeln('    /** ${values.length} entries. */')
      ..writeln('    val $name: List<String> by lazy {')
      ..writeln('        decode(')
      ..writeln('            ${_hex(seedFor(name))},');
    for (var i = 0; i < hex.length; i += 96) {
      final chunk = hex.substring(i, i + 96 > hex.length ? hex.length : i + 96);
      final sep = i + 96 >= hex.length ? ',' : ' +';
      out.writeln('            "$chunk"$sep');
    }
    out
      ..writeln('        )')
      ..writeln('    }');
  }
  out
    ..writeln()
    ..writeln('    private fun decode(seed: Int, hex: String): List<String> {')
    ..writeln('        val bytes = ByteArray(hex.length / 2) { i ->')
    ..writeln('            val b = hex.substring(i * 2, i * 2 + 2).toInt(16)')
    ..writeln('            (b xor ((seed + i * 167) and 0xff)).toByte()')
    ..writeln('        }')
    ..writeln('        return String(bytes, Charsets.UTF_8).split(\'\\u0000\')')
    ..writeln('    }')
    ..writeln('}');
  return out.toString();
}

/// [manifest] with the generated `<queries>` block replaced.
String generateManifest(String manifest, Map<String, List<String>> lists) {
  final start = manifest.indexOf(_beginQueries);
  final end = manifest.indexOf(_endQueries);
  if (start < 0 || end < start) {
    throw StateError(
      '$manifestPath is missing the generated <queries> markers',
    );
  }
  final lineStart = manifest.lastIndexOf('\n', start) + 1;
  final indent = manifest.substring(lineStart, start);
  final block = StringBuffer()
    ..writeln(_beginQueries)
    ..writeln('$indent<queries>');
  for (final list in queriedLists) {
    for (final p in lists[list] ?? const <String>[]) {
      block.writeln('$indent    <package android:name="$p" />');
    }
  }
  block
    ..writeln('$indent</queries>')
    ..write(indent);
  return manifest.replaceRange(start, end, block.toString());
}

/// Every generated file, keyed by path.
Map<String, String> generateAll(String json, String manifest) {
  final lists = readLists(json);
  return {
    cOut: generateC(lists),
    kotlinOut: generateKotlin(lists),
    manifestPath: generateManifest(manifest, lists),
  };
}

void main(List<String> args) {
  final check = args.contains('--check');
  final files = generateAll(
    File(jsonPath).readAsStringSync(),
    File(manifestPath).readAsStringSync(),
  );
  var stale = false;
  for (final MapEntry(key: path, value: content) in files.entries) {
    final file = File(path);
    final current = file.existsSync()
        ? file.readAsStringSync().replaceAll('\r\n', '\n')
        : null;
    if (current == content) continue;
    if (check) {
      stderr.writeln('Stale: $path');
      stale = true;
    } else {
      file.writeAsStringSync(content);
      stdout.writeln('Wrote $path');
    }
  }
  if (stale) {
    stderr.writeln('Run `dart run tool/gen_signatures.dart`.');
    exitCode = 1;
  }
}
